import os
import ops
from ops import testing

class MyCharm(ops.CharmBase):
    def __init__(self, *args):
        super().__init__(*args)
        self.framework.observe(self.on.update_status, self._on_update_status)

    def _on_update_status(self, _):
        assert os.getcwd() == self.framework.charm_dir

meta = {'name': 'my-charm', 'requires': {'db': {'interface': 'postgresql'}}}

ctx = testing.Context(MyCharm, meta=meta)
with ctx(ctx.on.update_status(), testing.State()) as mgr:
    mgr.charm.on.update_status.emit()

